SourceCode.Declaration:
/// <summary>
/// One counting line for DIRECT transfer mode. Deliberately carries no on-hand, counted or
/// variance quantity - the counter never sees system stock (blind counting).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectLineRow
{
    real lineNumber;
    str  itemNumber;
    str  itemName;
    str  siteId;
    str  warehouseId;
    str  locationId;
    str  batchId;
    str  serialId;
    int  passNumber;
    str  unitId;
    str  configId;
    str  sizeId;
    str  colorId;
    str  styleId;

    boolean recount;
    str locationType;
    str owner;
    boolean verifyOnly;
}

